import{_ as o,o as r,c as a,a2 as i}from"./chunks/framework.CnJ-JtFX.js";const c=JSON.parse('{"title":"EP.14 五强横评：没有银弹","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.14-product-comparison.md","filePath":"comics/EP.14-product-comparison.md","lastUpdated":1792683644000}'),e={name:"comics/EP.14-product-comparison.md"};function s(d,t,l,n,g,m){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="ep-14-五强横评-没有银弹" tabindex="-1">EP.14 五强横评：没有银弹 <a class="header-anchor" href="#ep-14-五强横评-没有银弹" aria-label="Permalink to &quot;EP.14 五强横评：没有银弹&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/14-product-comparison">guide/14-product-comparison</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君接到「客户运营后台」需求，面前摆着 amis / Formily / lowcode-engine / tmagic-editor / GrapesJS 五个产品，功能清单各有千秋，不知道选哪个，陷入选型焦虑。</li><li><strong>揭秘</strong>：像素酱掏出一张选型决策树——别比功能清单，先问自己三个问题：表单还是页面？自由还是约束？是否需要跨端？三问答完，选型范围立刻从 5 个缩小到 1-2 个。</li><li><strong>实证</strong>：拿同一个「客户运营后台」需求，分别用五个产品实现一遍——amis 半天搭完 CRUD 最快、Formily 复杂表单联动最强、lowcode-engine 物料插件最灵活、tmagic-editor 一套 DSL 跨端最好、GrapesJS 自由画布最自由。</li><li><strong>结案</strong>：码叔一锤定音——没有银弹，只有最适合场景的选型。amis 打中后台、Formily 打复杂表单、lowcode-engine 打深度定制、tmagic 打 H5 活动页、GrapesJS 打营销落地页。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-选型焦虑的本质" tabindex="-1">第一格：选型焦虑的本质 <a class="header-anchor" href="#第一格-选型焦虑的本质" aria-label="Permalink to &quot;第一格：选型焦虑的本质&quot;">​</a></h3><p>选型焦虑不是因为产品少，而是因为<strong>产品太多且各有所长</strong>。五个产品都能做「客户运营后台」，但开发效率、扩展空间、跨端能力、维护成本完全不同。如果不先定义场景边界，就会在功能清单里迷失。</p><p>选型的第一步不是看产品功能，而是<strong>定义需求边界</strong>：表单还是页面？单端还是多端？运营自服务还是研发交付？边界清楚了，候选产品自然就少了。</p><h3 id="第二格-选型决策树三问" tabindex="-1">第二格：选型决策树三问 <a class="header-anchor" href="#第二格-选型决策树三问" aria-label="Permalink to &quot;第二格：选型决策树三问&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>分支</th><th>推荐方向</th></tr></thead><tbody><tr><td>Q1 表单还是页面？</td><td>表单为主</td><td>Formily / amis</td></tr><tr><td>Q1 表单还是页面？</td><td>页面为主</td><td>进入 Q2</td></tr><tr><td>Q2 自由还是约束？</td><td>要自由画布</td><td>GrapesJS</td></tr><tr><td>Q2 自由还是约束？</td><td>要 Schema 约束</td><td>进入 Q3</td></tr><tr><td>Q3 是否跨端？</td><td>PC + H5 + 小程序</td><td>tmagic-editor</td></tr><tr><td>Q3 是否跨端？</td><td>单端 PC</td><td>amis / lowcode-engine</td></tr></tbody></table><p>三问的本质是<strong>逐级收敛</strong>：先按交付形态收敛（表单/页面），再按编辑范式收敛（自由/约束），最后按端能力收敛（单端/跨端）。每一问砍掉一半候选，三问之后就剩 1-2 个。</p><h3 id="第三格-五强实证对比" tabindex="-1">第三格：五强实证对比 <a class="header-anchor" href="#第三格-五强实证对比" aria-label="Permalink to &quot;第三格：五强实证对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>产品</th><th>优势</th><th>短板</th></tr></thead><tbody><tr><td>amis</td><td>JSON 配置半天搭完 CRUD，上线最快</td><td>灵活性差，定制组件成本高</td></tr><tr><td>Formily</td><td>表单联动、校验、字段模型最强</td><td>只做表单，页面搭建要自己拼</td></tr><tr><td>lowcode-engine</td><td>物料 + 插件体系，扩展空间最大</td><td>上手成本高，需要自研物料</td></tr><tr><td>tmagic-editor</td><td>一套 DSL 出 PC + H5 + 小程序</td><td>生态偏腾讯系，社区资料少</td></tr><tr><td>GrapesJS</td><td>自由画布，落地页排版最自由</td><td>没有表单模型，不适合中后台</td></tr></tbody></table><p>关键洞察：<strong>没有全能产品</strong>。每个产品都在某一个维度做到极致，同时在另一个维度妥协。选型就是选取舍——你愿意为哪个维度买单、愿意牺牲哪个维度。</p><h3 id="第四格-场景选型映射" tabindex="-1">第四格：场景选型映射 <a class="header-anchor" href="#第四格-场景选型映射" aria-label="Permalink to &quot;第四格：场景选型映射&quot;">​</a></h3><ul><li><strong>amis → 中后台系统</strong>：CRUD 密集、追求上线速度、运营配置为主。</li><li><strong>Formily → 复杂表单场景</strong>：联动多、校验重、字段多，表单是核心交互。</li><li><strong>lowcode-engine → 深度定制化</strong>：有研发资源、要自研物料和插件体系。</li><li><strong>tmagic-editor → H5 活动页</strong>：多端投放、一套 DSL、运营频繁上线。</li><li><strong>GrapesJS → 营销落地页</strong>：自由排版、视觉为主、运营自服务。</li></ul><p>记住一句话：<strong>选型 = 场景匹配，不是技术崇拜</strong>。别问&quot;哪个产品最好&quot;，要问&quot;这个场景最需要哪个能力&quot;。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>只看功能清单不看场景</strong>：五个产品功能列表都很长，逐项对比永远选不出来。先定场景再看功能，场景不匹配的功能再强也没用。</li><li><strong>低估自研成本</strong>：lowcode-engine 灵活但需要自研物料和插件，没有 2-3 个前端长期投入很难跑通。团队人手不足时，amis 的&quot;开箱即用&quot;反而更划算。</li><li><strong>跨端需求想当然</strong>：tmagic-editor 的跨端是&quot;一套 DSL 多端渲染&quot;，但端能力差异大的组件（如地图、视频）仍要写多端适配。不是写一次就真的到处跑。</li><li><strong>GrapesJS 用于中后台表单</strong>：GrapesJS 没有表单字段模型，联动和校验要手动写 JS，提交要遍历 DOM 收值。中后台表单用 amis/Formily 效率高一个数量级。</li><li><strong>把 amis 当万能</strong>：amis 适合标准 CRUD，但定制交互（如复杂拖拽、自定义布局）要写自定义组件，成本不比自研低。超出标准场景时要及时换方案。</li><li><strong>忽视生态和社区</strong>：tmagic-editor 资料偏腾讯系，GrapesJS 是英文社区，amis 中文社区最活跃。遇到问题时，社区活跃度直接决定排障速度。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 为什么说选型决策树的三问是&quot;逐级收敛&quot;而不是&quot;并列筛选&quot;？</b></summary><p>因为三个问题有依赖关系，必须按顺序问：</p><ol><li><strong>先定交付形态</strong>（表单还是页面）——这是最粗的粒度，直接砍掉一半候选。表单为主的场景，GrapesJS 这种自由画布基本不用考虑；页面为主的场景，Formily 这种纯表单引擎也不合适。</li><li><strong>再定编辑范式</strong>（自由还是约束）——确定是页面后，再问运营要自由拖拽还是要 Schema 约束。自由拖拽选 GrapesJS，要约束就进入第三问。</li><li><strong>最后定端能力</strong>（单端还是跨端）——确定要约束后，再问是否需要跨端。跨端选 tmagic，单端选 amis 或 lowcode-engine。</li></ol><p>如果并列筛选，会出现&quot;表单但要跨端&quot;这种矛盾组合，反而选不出来。逐级收敛保证每一步都在缩小范围，不会出现死胡同。</p></details><details><summary><b>2. 同一个&quot;客户运营后台&quot;需求，为什么 five 个产品都能做但体验天差地别？</b></summary><p>因为&quot;能做&quot;和&quot;做得好&quot;是两回事：</p><ul><li><strong>amis</strong>：JSON 配置半天搭完，上线快，但定制交互要写自定义组件。</li><li><strong>Formily</strong>：表单部分极强，但列表、看板等页面元素要自己用 React 拼。</li><li><strong>lowcode-engine</strong>：灵活度最高，但物料和插件要自研，前期投入大。</li><li><strong>tmagic-editor</strong>：一套 DSL 出多端，但 PC 端中后台的复杂交互不如 amis 顺手。</li><li><strong>GrapesJS</strong>：自由排版，但表单联动和数据提交要手动处理。</li></ul><p>差异的根源是<strong>每个产品的设计目标不同</strong>：amis 目标是&quot;快速交付标准中后台&quot;，Formily 目标是&quot;管好复杂表单&quot;，lowcode-engine 目标是&quot;搭建可定制的搭建平台&quot;，tmagic 目标是&quot;多端投放&quot;，GrapesJS 目标是&quot;自由视觉搭建&quot;。目标不同，能力侧重就不同。</p><p>所以选型不是找&quot;能做的&quot;，而是找&quot;做得最顺手的&quot;——同一个需求，用错产品就是事倍功半。</p></details><details><summary><b>3. 如果团队只有 1 个前端，要做一个带复杂表单的中后台，该怎么选？</b></summary><p>推荐 <strong>amis</strong>，理由：</p><ol><li><strong>人少优先开箱即用</strong>：lowcode-engine 需要自研物料和插件，1 个人撑不起物料生态；GrapesJS 要自己管表单联动和数据提交，中后台场景下工作量大。amis 开箱即用，JSON 配置就能搭 CRUD，1 个人能扛住。</li><li><strong>复杂表单 amis 能覆盖 80%</strong>：amis 的表单组件联动（source、autoFill、visibleOn）能覆盖大多数中后台表单场景，虽然不如 Formily 灵活，但够用。</li><li><strong>如果表单真的极其复杂</strong>（如动态字段、跨字段校验、自定义渲染），可以在 amis 里嵌入 Formily 作为自定义组件——amis 管页面骨架和数据，Formily 管复杂表单局部。这是大厂常用的组合拳。</li></ol><p>不推荐 lowcode-engine 的原因：1 个前端要同时做物料、插件、设计器、渲染器，半年都跑不通 MVP，业务等不起。</p></details>',23)])])}const h=o(e,[["render",s]]);export{c as __pageData,h as default};
